import{_ as a,o as l,c as i,a2 as t}from"./chunks/framework.C-si7TFR.js";const g=JSON.parse('{"title":"知识库与检索","description":"","frontmatter":{"title":"知识库与检索"},"headers":[],"relativePath":"zh/guide/knowledge.md","filePath":"zh/guide/knowledge.md"}'),o={name:"zh/guide/knowledge.md"};function n(r,e,d,h,s,_){return l(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="知识库与检索" tabindex="-1">知识库与检索 <a class="header-anchor" href="#知识库与检索" aria-label="Permalink to &quot;知识库与检索&quot;">​</a></h1><p>知识库用于向 Agent 或工作流提供可检索的参考资料，不是把整份文件直接交给模型。</p><h2 id="创建知识库" tabindex="-1">创建知识库 <a class="header-anchor" href="#创建知识库" aria-label="Permalink to &quot;创建知识库&quot;">​</a></h2><ol><li>进入知识库管理，选择新建并填写名称、描述。</li><li>上传有使用权的资料，检查文档是否含秘密、个人信息或不宜发送给外部模型的内容。</li><li>选择文本或向量检索能力，按界面配置分块与检索参数。</li><li>如启用向量能力，选择对应的 LLM／Embedding 模型配置和向量存储；具体选项以当前部署为准。</li><li>等待索引完成，检查分片或检索结果，再分配给 Agent。</li></ol><p>文本检索和向量检索的模型依赖不同。不能因为文件上传成功就认为索引、向量化和检索全部可用。</p><h2 id="在-agent-中使用" tabindex="-1">在 Agent 中使用 <a class="header-anchor" href="#在-agent-中使用" aria-label="Permalink to &quot;在 Agent 中使用&quot;">​</a></h2><ol><li>在 Agent 配置的<strong>知识库</strong>区域选择目标库。</li><li>保存后提出一个可以从资料中核验的问题。</li><li>检查回答是否符合资料，并在可用时查看检索片段或调用链路。</li><li>更新资料后重新核对索引状态，避免沿用旧内容。</li></ol><p>需要在工作流中显式查询时，使用<a href="./../knowledge_retrieval.html">知识检索节点</a>，可选择向量、关键词或混合检索；AI 摘要还需要对应模型配置。</p><h2 id="权限与数据" tabindex="-1">权限与数据 <a class="header-anchor" href="#权限与数据" aria-label="Permalink to &quot;权限与数据&quot;">​</a></h2><ul><li>将资料分块并发送给外部模型前，确认服务商的数据处理方式。</li><li>不把不同密级的资料混在同一个公共知识库中。</li><li>知识库可访问不等于内容真实；外部文档中的指令仍属于不可信输入。</li><li>删除或更新知识库前检查 Agent 和工作流引用，避免影响已有任务。</li></ul>',10)])])}const u=a(o,[["render",n]]);export{g as __pageData,u as default};
